// 1. Input Validation
int valid_input = 1;

if (!wo_input.enable) {
    wo_state.mode = WO_FAULT;
}

if (wo_input.wheel_count != 4) {
    valid_input = 0;
}

if (wo_input.wheels == NULL) {
    valid_input = 0;
} else {
    for (size_t i = 0; i < 4; ++i) {
        if (!isfinite(wo_input.wheels[i].speed_rad_s)) {
            valid_input = 0;
            break;
        }
    }
}

if (valid_input) {
    if (!isfinite(wo_config.release_rad_s) || !isfinite(wo_config.warn_rad_s) || 
        !isfinite(wo_config.trip_rad_s) ||
        !isfinite(wo_config.derate_torque_nm) || !isfinite(wo_config.brake_torque_nm) ||
        !isfinite(wo_config.torque_slew_nm_per_cycle) || !isfinite(wo_config.dt_s)) {
        valid_input = 0;
    } else if (!(wo_config.release_rad_s >= 0 && wo_config.release_rad_s < wo_config.warn_rad_s && 
                 wo_config.warn_rad_s < wo_config.trip_rad_s)) {
        valid_input = 0;
    } else if (wo_config.derate_torque_nm <= 0 || wo_config.brake_torque_nm <= 0) {
        valid_input = 0;
    } else if (wo_config.torque_slew_nm_per_cycle <= 0 || wo_config.dt_s <= 0) {
        valid_input = 0;
    } else if (wo_config.release_cycles < 1 || wo_config.release_cycles > 100 ||
               wo_config.minimum_brake_cycles < 1 || wo_config.minimum_brake_cycles > 100 ||
               wo_config.cooldown_cycles < 1 || wo_config.cooldown_cycles > 100) {
        valid_input = 0;
    }

    if (wo_config.brake_torque_nm < wo_config.derate_torque_nm) {
        valid_input = 0;
    }
}

if (!valid_input) {
    wo_state.mode = WO_FAULT;
}

// Initialize Output
wo_output.limited_mask = 0;
wo_output.maximum_speed_rad_s = 0.0;
wo_output.momentum_norm_nms = 0.0;
wo_output.dissipated_energy_j = wo_state.dissipated_energy_j;
wo_output.brake_power_w = 0.0;
wo_output.momentum_nms.x = 0.0;
wo_output.momentum_nms.y = 0.0;
wo_output.momentum_nms.z = 0.0;

for (int i = 0; i < 4; ++i) {
    wo_output.wheel_torque_nm[i] = 0.0;
}

if (wo_state.mode != WO_FAULT) {
    // 2. Momentum
    adcs_status_t stat = adcs_wheel_momentum(wo_input.wheels, 4, &wo_output.momentum_nms);
    if (stat != ADCS_OK || !isfinite(wo_output.momentum_nms.x) || 
        !isfinite(wo_output.momentum_nms.y) || !isfinite(wo_output.momentum_nms.z)) {
        wo_state.mode = WO_FAULT;
    } else {
        wo_output.momentum_norm_nms = adcs_vec3_norm(&wo_output.momentum_nms);
    }

    // 3. Max Speed
    double max_abs_speed = 0.0;
    for (int i = 0; i < 4; ++i) {
        double s = fabs(wo_input.wheels[i].speed_rad_s);
        if (s > max_abs_speed) max_abs_speed = s;
    }
    wo_output.maximum_speed_rad_s = max_abs_speed;

    // 4. Mode Transition
    wo_mode_t next_mode = wo_state.mode;
    static unint32 release_ev = 0;

    switch (wo_state.mode) {
        case WO_NORMAL:
            if (max_abs_speed >= wo_config.trip_rad_s) next_mode = WO_BRAKE;
            else if (max_abs_speed >= wo_config.warn_rad_s) next_mode = WO_DERATE;
            else next_mode = WO_NORMAL;
            break;
        case WO_DERATE:
            if (max_abs_speed >= wo_config.trip_rad_s) next_mode = WO_BRAKE;
            else {
                if (max_abs_speed <= wo_config.release_rad_s) release_ev++;
                else release_ev = 0;

                if (release_ev >= wo_config.release_cycles) next_mode = WO_NORMAL;
                else next_mode = WO_DERATE;
            }
            break;
        case WO_BRAKE:
            wo_state.elapsed++;
            if (max_abs_speed >= wo_config.trip_rad_s) {
                next_mode = WO_BRAKE;
            } else {
                if (wo_state.elapsed >= wo_config.minimum_brake_cycles) {
                    if (max_abs_speed <= wo_config.release_rad_s) release_ev++;
                    else release_ev = 0;

                    if (release_ev >= wo_config.release_cycles) next_mode = WO_COOLDOWN;
                    else next_mode = WO_BRAKE;
                } else {
                    next_mode = WO_BRAKE;
                }
            }
            break;
        case WO_COOLDOWN:
            wo_state.elapsed++;
            if (max_abs_speed >= wo_config.trip_rad_s) {
                next_mode = WO_BRAKE;
                wo_state.elapsed = 0;
            } else {
                if (wo_state.elapsed >= wo_config.cooldown_cycles) next_mode = WO_NORMAL;
                else next_mode = WO_COOLDOWN;
            }
            break;
        default:
            next_mode = WO_FAULT;
    }

    if (next_mode != wo_state.mode) {
        wo_state.clean = 0;
        if (next_mode == WO_BRAKE || next_mode == WO_COOLDOWN) {
            wo_state.elapsed = 0;
        }
        release_ev = 0;
        wo_state.mode = next_mode;
    } else {
        wo_state.clean = 1;
    }

    // 5. Torque Calc
    double raw_t[4];
    for (int i = 0; i < 4; ++i) {
        raw_t[i] = 0.0;
        double spd = wo_input.wheels[i].speed_rad_s;
        double abs_spd = fabs(spd);

        if (wo_state.mode == WO_DERATE && abs_spd > wo_config.release_rad_s) {
            double ex = abs_spd - wo_config.release_rad_s;
            double den = wo_config.trip_rad_s - wo_config.release_rad_s;
            double r = (den > 0) ? (ex / den) : 0.0;
            if (r > 1.0) r = 1.0;
            double mag = wo_config.derate_torque_nm * r;
            raw_t[i] = -copysign(mag, spd);
        } else if (wo_state.mode == WO_BRAKE && abs_spd > FLT64_ZERO) {
            raw_t[i] = -copysign(wo_config.brake_torque_nm, spd);
        }
    }

    // 6. Slew
    double lim_t[4];
    for (int i = 0; i < 4; ++i) {
        double prev = wo_state.previous_wheel_torque_nm[i];
        double d = raw_t[i] - prev;
        double sl = wo_config.torque_slew_nm_per_cycle;

        if (d > sl) {
            lim_t[i] = prev + sl;
            wo_output.limited_mask |= (1 << i);
        } else if (d < -sl) {
            lim_t[i] = prev - sl;
            wo_output.limited_mask |= (1 << i);
        } else {
            lim_t[i] = raw_t[i];
        }

        wo_output.wheel_torque_nm[i] = lim_t[i];
        wo_state.previous_wheel_torque_nm[i] = lim_t[i];
    }

    // 7. Power/Energy
    double pwr = 0.0;
    for (int i = 0; i < 4; ++i) {
        pwr += lim_t[i] * wo_input.wheels[i].speed_rad_s;
    }
    wo_output.brake_power_w = pwr;
    wo_state.dissipated_energy_j += (-pwr) * wo_config.dt_s;
    wo_output.dissipated_energy_j = wo_state.dissipated_energy_j;
}

