            w[i].inertia_kg_m2 < 0.0 || 
            !isfinite(w[i].axis_body.x) || !isfinite(w[i].axis_body.y) || !isfinite(w[i].axis_body.z)) {
            valid_input = 0;
            break;
        }
    }
}

