    if (diff > slew) {
        limited_torque = prev_torque + slew;
    } else if (diff < -slew) {
        limited_torque = prev_torque - slew;
    }

    wo_output.wheel_torque_nm[i] = limited_torque;

    // Raw power for energy calc (torque * speed)
    total_raw_power += limited_torque * speed;

    // Update previous torque
    wo_state.previous_wheel_torque_nm[i] = limited_torque;
}

// Energy Accumulation: energy += -power * dt
// total_raw_power is negative (dissipation). -total_raw_power is positive.
if (fault_detected == 0) {
    wo_state.dissipated_energy_j += (-total_raw_power) * wo_config.dt_s;
    wo_output.dissipated_energy_j = wo_state.dissipated_energy_j;

    // Brake Power (Dissipative, positive)
    wo_output.brake_power_w = -total_raw_power;

    // Limited Mask
    uint32_t mask = 0;
    for (int i = 0; i < 4; i++) {
        if (fabs(wo_output.wheel_torque_nm[i]) > 0.0) {
            mask |= (1U << i);
        }
    }
    wo_output.limited_mask = mask;
}

// Handle Fault Latch Logic
if (fault_detected) {
    wo_state.mode = WO_FAULT;
    wo_output.mode = WO_FAULT;
    wo_output.clean = 0;
    wo_output.elapsed = 0;
    wo_output.limited_mask = 0;
    for (int i = 0; i < 4; i++) {
        wo_output.wheel_torque_nm[i] = 0.0;
        wo_state.previous_wheel_torque_nm[i] = 0.0;
    }
    wo_output.maximum_speed_rad_s = 0.0;
    wo_output.brake_power_w = 0.0;
    // Energy is NOT reset
    wo_output.dissipated_energy_j = wo_state.dissipated_energy_j;
    wo_output.momentum_nms.x = 0.0;
    wo_output.momentum_nms.y = 0.0;
    wo_output.momentum_nms.z = 0.0;
    wo_output.momentum_norm_nms = 0.0;
}
